// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for the functions we need
interface IOptiFi {
    function owner() external view returns (address);
    function setBotBlacklist(address _botAddress, bool _flag) external;
    function blacklist(address) external view returns (bool);
}

// Concrete implementation instead of abstract contract
contract OptiFi is IOptiFi {
    address public owner;
    mapping(address => bool) public blacklist;

    constructor() {
        owner = msg.sender;
    }

    function setBotBlacklist(address _botAddress, bool _flag) external {
        require(msg.sender == owner, "Only owner");
        blacklist[_botAddress] = _flag;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    // State variable for the locally deployed contract
    OptiFi public opti;

    address constant TARGET = 0xb5D5D9C8E98cef68E7bdAd92b1De229d514179b6;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Deploy the contract locally
        opti = new OptiFi();
        // Label for clarity
        vm.label(address(opti), "OptiFi Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Deploy the contract locally (already done in setUp)
        // Now test the owner privilege
        address victim = address(0x1234567890123456789012345678901234567890);

        // The deployer (address(this)) is the owner, so we can call setBotBlacklist directly
        opti.setBotBlacklist(victim, true);

        // Verify the blacklist was set correctly
        bool isBlacklisted = opti.blacklist(victim);
        assertEq(isBlacklisted, true, "Victim should be blacklisted");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

